// ProgramRuntime-level qualification of the durable provider dispatch journal (#295).
//
// Every call identity below is generated by ProgramRuntime/Core; no test builds a
// ProgramCoreProviderCallContext or ProviderCallIdentity by hand to start a run.
// Recovery is real: runtime, catalog, engine cache, journal, transition/program
// store and checkpoint store are destroyed and reopened from their SQLite files
// (or from a byte-consistent crash image of them) before the run is continued.
#include <neograph/program/program.h>
#include <neograph/program/sqlite_provider_call_broker.h>
#include <neograph/program/sqlite_store.h>
#include <neograph/program/sqlite_transition_store.h>
#include <neograph/graph/node.h>
#include <neograph/graph/sqlite_checkpoint.h>
#include <neograph/tool_dispatch.h>
#include <neograph/tool_effect_broker.h>
#include "fixtures/typed_provider.h"

#include <sqlite3.h>
#include <gtest/gtest.h>

#include <algorithm>
