TEST(ProgramProviderJournalRuntime, OverlappingRunsOnOneAdmittedEngineJournalUnderTheirOwnKeys) {
    TempDir files("overlap");
    auto shared = std::make_shared<Shared>();
    Rendezvous both_in_flight(3);
    shared->on_transport = [&](int, const ProviderRequest&) { both_in_flight.arrive_and_wait(); };
    std::string version_a, version_b;
    {
        Options options;
        options.threads = 3;
        Wire wire(files, shared, options);
        const auto a = wire.admit("tenant:a", Topology::Llm);
        const auto b = wire.admit("tenant:b", Topology::Llm);
        version_a = a.id();
        version_b = b.id();
        auto first = wire.runtime().start("tenant:a", a, wire.invocation("run-a1", "question-a1", Topology::Llm));
        auto second = wire.runtime().start("tenant:a", a, wire.invocation("run-a2", "question-a2", Topology::Llm));
        auto third = wire.runtime().start("tenant:b", b, wire.invocation("run-b1", "question-b1", Topology::Llm));
        const auto left = first.wait();
        const auto middle = second.wait();
        const auto right = third.wait();
        for (const auto* result : {&left, &middle, &right})
            ASSERT_EQ(result->status(), ProgramTerminalStatus::Completed) << failure_text(*result);
        EXPECT_EQ(both_in_flight.arrived(), 3) << "all three transports were in flight together";
        EXPECT_NE(left.output().dump().find("answer(question-a1)"), std::string::npos);
        EXPECT_NE(middle.output().dump().find("answer(question-a2)"), std::string::npos);
        EXPECT_NE(right.output().dump().find("answer(question-b1)"), std::string::npos);
    }
    EXPECT_EQ(shared->transport.load(), 3);
    const auto observed = shared->snapshot();
    ASSERT_EQ(observed.size(), 3U);
    std::set<std::string> engines;
    for (const auto& call : observed) engines.insert(call.generation);
    EXPECT_EQ(engines.size(), 1U) << "both owners and all runs must dispatch through one admitted engine";

    const auto all = rows(files.provider_db());
    ASSERT_EQ(all.size(), 3U);
    std::set<std::string> ids, threads, requests;
    const std::map<std::string, std::pair<std::string, std::string>> expected{
        {"run-a1", {"tenant:a", version_a}}, {"run-a2", {"tenant:a", version_a}},
        {"run-b1", {"tenant:b", version_b}}};
    for (const auto& [run, owner_version] : expected) {
        const auto& row = row_for_run(all, run);
        EXPECT_EQ(row.owner, owner_version.first);
        EXPECT_EQ(row.slot.at("owner_scope"), owner_version.first);
        EXPECT_EQ(row.slot.at("program_version_id"), owner_version.second);
        EXPECT_EQ(row.slot.at("operation_id"), "root");
        EXPECT_EQ(row.slot.at("node_name"), "llm");
        EXPECT_EQ(row.slot.at("call_ordinal"), 0);
        EXPECT_FALSE(row.slot.at("thread_id").get<std::string>().empty());
        EXPECT_FALSE(row.slot.at("task_id").get<std::string>().empty());
        EXPECT_EQ(row.state, "succeeded");
        EXPECT_EQ(row.original_attempt, "1");
        ids.insert(row.id);
        threads.insert(row.slot.at("thread_id").get<std::string>());
        requests.insert(row.request);
    }
    EXPECT_EQ(ids.size(), 3U);
    EXPECT_EQ(threads.size(), 3U) << "each run owns its Core thread";
    EXPECT_EQ(requests.size(), 3U) << "no run's request was bound to another run's slot";

    // A cold process: the three completions are recovered, never re-dispatched,
    // and an owner can read only its own receipts.
    Wire reopened(files, shared);
    for (const auto& [run, owner_version] : expected) {
        const auto restored = reopened.runtime().reconnect(owner_version.first, run).wait();
        EXPECT_EQ(restored.status(), ProgramTerminalStatus::Completed);
        EXPECT_NE(restored.output().dump().find("answer(question-" + run.substr(4) + ")"),
                  std::string::npos);
        const auto& row = row_for_run(all, run);
        const auto receipt = reopened.journal().inspect(owner_version.first, row.id);
        ASSERT_TRUE(receipt);
        EXPECT_EQ(receipt->state, Journal::State::Succeeded);
        EXPECT_FALSE(reopened.journal().inspect(owner_version.first == "tenant:a" ? "tenant:b" : "tenant:a",
                                                row.id));
    }
    EXPECT_EQ(shared->transport.load(), 3);
    EXPECT_TRUE(same_rows(rows(files.provider_db()), all));
}

