TEST(ProgramProviderJournalRuntime, AdvancedAttemptReusesCompletedSlotWithoutTransport) {
    TempDir files("advance");
    auto shared = std::make_shared<Shared>();
    shared->interrupt_after_call = true;
    const std::string owner = "tenant:advance";
    const std::string run = "advance-run";
    ProgramResult interrupted;
    std::vector<Row> before;
    {
        Wire wire(files, shared);
        const auto version = wire.admit(owner, Topology::Approval);
        interrupted = wire.runtime().run(owner, version, wire.invocation(run, "", Topology::Approval));
        ASSERT_EQ(interrupted.status(), ProgramTerminalStatus::Interrupted) << failure_text(interrupted);
        EXPECT_EQ(interrupted.attempt(), 1U);
        EXPECT_EQ(shared->transport.load(), 1);
        before = rows(files.provider_db());
        ASSERT_EQ(before.size(), 1U);
        EXPECT_EQ(before[0].state, "succeeded");
        EXPECT_EQ(before[0].original_attempt, "1");
    }
    Wire reopened(files, shared);
    const auto reconnected = reopened.runtime().reconnect(owner, run).wait();
    ASSERT_EQ(reconnected.status(), ProgramTerminalStatus::Interrupted);
    EXPECT_EQ(shared->transport.load(), 1);

    const auto resumed = reopened.runtime().resume(owner, run, resume_after(interrupted, "trace-advance-resume")).wait();
    ASSERT_EQ(resumed.status(), ProgramTerminalStatus::Completed) << failure_text(resumed);
    EXPECT_EQ(resumed.attempt(), 2U) << "resume advanced the Program attempt";
    EXPECT_EQ(shared->transport.load(), 1) << "the existing completion was reused, not dispatched again";
    EXPECT_NE(resumed.output().dump().find("answer(question)"), std::string::npos);
    const auto after = rows(files.provider_db());
    ASSERT_EQ(after.size(), 1U) << "attempt is provenance, not part of the logical slot";
    EXPECT_EQ(after[0].id, before[0].id);
    EXPECT_EQ(after[0].original_attempt, "1");
    EXPECT_TRUE(same_rows(after, before));
    ASSERT_TRUE(reopened.journal().inspect(owner, after[0].id));
    EXPECT_EQ(reopened.journal().inspect(owner, after[0].id)->original_attempt, "1");
}

