TEST(ProgramProviderJournalRuntime, MarkerWriteFailureDispatchesNothing) {
    TempDir files("marker-fault");
    auto shared = std::make_shared<Shared>();
    Wire wire(files, shared);
    const auto version = wire.admit("tenant:fault", Topology::Llm);
    Connection fault(files.provider_db());
    fault.exec("CREATE TRIGGER deny_marker BEFORE INSERT ON ng_program_provider_calls "
               "BEGIN SELECT RAISE(FAIL, 'injected marker failure'); END");
    const auto failed = wire.runtime().run("tenant:fault", version,
                                           wire.invocation("fault-run", "question", Topology::Llm));
    EXPECT_EQ(failed.status(), ProgramTerminalStatus::Failed);
    EXPECT_NE(failure_text(failed).find("injected marker failure"), std::string::npos)
        << failure_text(failed);
    EXPECT_EQ(shared->transport.load(), 0) << "no marker, no Provider call";
    EXPECT_TRUE(rows(files.provider_db()).empty());
    // The trigger was the only cause: the same Program dispatches once it is gone.
    fault.exec("DROP TRIGGER deny_marker");
    const auto healthy = wire.runtime().run("tenant:fault", version,
                                            wire.invocation("healthy-run", "question", Topology::Llm));
    EXPECT_EQ(healthy.status(), ProgramTerminalStatus::Completed) << failure_text(healthy);
    EXPECT_EQ(shared->transport.load(), 1);
    EXPECT_EQ(rows(files.provider_db()).size(), 1U);
}

