TEST(ProgramProviderJournalRuntime, FailureAfterDispatchLeavesUncertainMarkerThatReconnectNeverRedispatches) {
    TempDir files("uncertain");
    auto shared = std::make_shared<Shared>();
    shared->on_transport = [](int, const ProviderRequest&) {
        throw std::runtime_error("link lost after the request was sent");
    };
    const std::string owner = "tenant:uncertain";
    std::string run_id;
    {
        Wire wire(files, shared);
        const auto version = wire.admit(owner, Topology::Llm);
        const auto failed = wire.runtime().run(owner, version,
                                               wire.invocation("uncertain-run", "question", Topology::Llm));
        ASSERT_EQ(failed.status(), ProgramTerminalStatus::Failed);
        run_id = failed.run_id();
    }
    EXPECT_EQ(shared->transport.load(), 1);
    const auto before = rows(files.provider_db());
    ASSERT_EQ(before.size(), 1U);
    EXPECT_EQ(before[0].state, "reconciliation_required");
    shared->on_transport = {};   // the Provider is healthy again: a redispatch would now succeed
    Wire reopened(files, shared);
    const auto restored = reopened.runtime().reconnect(owner, run_id).wait();
    EXPECT_EQ(restored.status(), ProgramTerminalStatus::Failed);
    EXPECT_EQ(shared->transport.load(), 1);
    EXPECT_TRUE(same_rows(rows(files.provider_db()), before));
    ASSERT_TRUE(reopened.journal().inspect(owner, before[0].id));
    EXPECT_EQ(reopened.journal().inspect(owner, before[0].id)->state, Journal::State::ReconciliationRequired);
}

TEST(ProgramProviderJournalRuntime, UncertainMarkerSurvivesAdvancedAttemptUntilExternallyReconciled) {
    TempDir files("uncertain-resume");
    auto shared = std::make_shared<Shared>();
    shared->interrupt_on_uncertain = true;
    shared->on_transport = [](int, const ProviderRequest&) {
        throw std::runtime_error("link lost after the request was sent");
    };
    const std::string owner = "tenant:uncertain";
    ProgramResult interrupted;
    {
        Wire wire(files, shared);
        const auto version = wire.admit(owner, Topology::Approval);
        interrupted = wire.runtime().run(owner, version, wire.invocation("uncertain-a", "", Topology::Approval));
        ASSERT_EQ(interrupted.status(), ProgramTerminalStatus::Interrupted) << failure_text(interrupted);
    }
    shared->on_transport = {};   // healthy again: any redispatch would succeed and be visible
    const auto before = rows(files.provider_db());
    ASSERT_EQ(before.size(), 1U);
    EXPECT_EQ(before[0].state, "reconciliation_required");
    ASSERT_EQ(shared->transport.load(), 1);

    // Same persisted state, two continuations.
    TempDir reconciled_files("uncertain-reconciled");
    copy_closed_files(files.path, reconciled_files.path);
    {
        Wire reopened(files, shared);
        const auto resumed = reopened.runtime().resume(owner, "uncertain-a",
            resume_after(interrupted, "trace-uncertain-resume")).wait();
        EXPECT_EQ(resumed.status(), ProgramTerminalStatus::Failed) << "attempt 2 must not re-dispatch";
        EXPECT_EQ(resumed.attempt(), 2U);
        EXPECT_NE(failure_text(resumed).find(
                      "dispatch outcome uncertain; reconciliation required"), std::string::npos)
            << failure_text(resumed);
        EXPECT_EQ(shared->transport.load(), 1);
        EXPECT_TRUE(same_rows(rows(files.provider_db()), before));
    }
    auto isolated = std::make_shared<Shared>();
    isolated->interrupt_on_uncertain = true;
    Wire reconciled(reconciled_files, isolated);
    reconciled.journal().reconcile_success(owner, before[0].id, digest('c'),
                                           neograph::test::success("confirmed externally"));
    const auto completed = reconciled.runtime().resume(owner, "uncertain-a",
        resume_after(interrupted, "trace-uncertain-reconciled")).wait();
    ASSERT_EQ(completed.status(), ProgramTerminalStatus::Completed) << failure_text(completed);
    EXPECT_EQ(completed.attempt(), 2U);
    EXPECT_NE(completed.output().dump().find("confirmed externally"), std::string::npos);
    EXPECT_EQ(isolated->transport.load(), 0) << "reconciled evidence replays without transport";
    const auto after = rows(reconciled_files.provider_db());
    ASSERT_EQ(after.size(), 1U);
    EXPECT_EQ(after[0].state, "succeeded");
    EXPECT_EQ(after[0].original_attempt, "1");
}

TEST(ProgramProviderJournalRuntime, CrashBetweenMarkerAndOutcomeIsNeverRedispatchedByRecovery) {
    TempDir files("crash");
    TempDir image("crash-image");
    auto shared = std::make_shared<Shared>();
    shared->interrupt_before_call = true;
    Options options;
    options.child_capable = true;
    // Snapshot attempt 2 while transport is in flight. Attempt 1 supplied a
    // durable node-interrupt checkpoint, so cold reconnect must actually
    // revisit the runtime-generated slot rather than merely reject a lease.
    shared->on_transport = [&](int, const ProviderRequest&) { crash_image(files.path, image.path); };
    const std::string owner = "tenant:crash";
    {
        Wire wire(files, shared, options);
        const auto version = wire.admit(owner, Topology::Approval);
        const auto paused = wire.runtime().run(owner, version,
            wire.invocation("crash-run", "", Topology::Approval));
        ASSERT_EQ(paused.status(), ProgramTerminalStatus::Interrupted) << failure_text(paused);
        ASSERT_EQ(shared->transport.load(), 0);
        ASSERT_TRUE(rows(files.provider_db()).empty());
        const auto done = wire.runtime().resume(owner, "crash-run",
            resume_after(paused, "trace-crash-resume")).wait();
        ASSERT_EQ(done.status(), ProgramTerminalStatus::Completed) << failure_text(done);
        ASSERT_EQ(done.attempt(), 2U);
    }
    ASSERT_EQ(shared->transport.load(), 1);
    const auto crashed = rows(image.provider_db());
    ASSERT_EQ(crashed.size(), 1U);
    EXPECT_EQ(crashed[0].state, "dispatched");
    EXPECT_EQ(crashed[0].original_attempt, "2");
    {
        SQLiteProgramTransitionStore transitions(image.program_db());
        const auto record = transitions.load(owner, "crash-run");
        ASSERT_TRUE(record);
        ASSERT_TRUE(record->exact_checkpoint());
        EXPECT_FALSE(record->terminal_result());
        EXPECT_EQ(record->continuation().state, ContinuationState::Running);
        EXPECT_EQ(record->continuation().attempt, 2U);
    }

    auto recovery = std::make_shared<Shared>();
    recovery->interrupt_before_call = true;
    Wire restarted(image, recovery, options);
    const auto recovered = restarted.runtime().reconnect(owner, "crash-run").wait();
    EXPECT_EQ(recovered.status(), ProgramTerminalStatus::Failed) << "the lost outcome needs reconciliation";
    EXPECT_EQ(recovered.attempt(), 2U);
    EXPECT_NE(failure_text(recovered).find(
                  "dispatch outcome uncertain; reconciliation required"), std::string::npos)
        << failure_text(recovered);
    EXPECT_EQ(recovery->transport.load(), 0) << "recovery must not send the unconfirmed request again";
    EXPECT_EQ(recovery->tool_executions.load(), 0);
    EXPECT_TRUE(same_rows(rows(image.provider_db()), crashed));
}

TEST(ProgramProviderJournalRuntime, RootExecutionLeaseRejectsCrashRecoveryBeforeFirstCheckpoint) {
    TempDir files("crash-first");
    TempDir image("crash-first-image");
    auto shared = std::make_shared<Shared>();
    shared->on_transport = [&](int, const ProviderRequest&) { crash_image(files.path, image.path); };
    const std::string owner = "tenant:crash";
    {
        Wire wire(files, shared);
        const auto version = wire.admit(owner, Topology::Llm);
        ASSERT_EQ(wire.runtime().run(owner, version,
                      wire.invocation("crash-run", "question", Topology::Llm)).status(),
                  ProgramTerminalStatus::Completed);
    }
    const auto crashed = rows(image.provider_db());
    ASSERT_EQ(crashed.size(), 1U);
    EXPECT_EQ(crashed[0].state, "dispatched");
    auto recovery = std::make_shared<Shared>();
    Wire restarted(image, recovery);
    try {
        (void)restarted.runtime().reconnect(owner, "crash-run");
        FAIL() << "the captured root execution lease must still fence reconnect";
    } catch (const ProgramDiagnosticError& error) {
        EXPECT_EQ(error.diagnostic().code, "P_RUN_LEASE_HELD");
    }
    EXPECT_EQ(recovery->transport.load(), 0);
    EXPECT_TRUE(same_rows(rows(image.provider_db()), crashed));
}

