namespace {
// A run that completed its model call, then paused for approval: attempt 1 is
// durable, attempt 2 is about to execute the same logical slot.
struct PausedWithCompletedCall {
    PausedWithCompletedCall() : files("conflict-source") {
        auto shared = std::make_shared<Shared>();
        shared->interrupt_after_call = true;
        Options options;
        options.model_tokens = 0;
        Wire wire(files, shared, options);
        const auto version = wire.admit(owner, Topology::Approval);
        interrupted = wire.runtime().run(owner, version, wire.invocation(run, "", Topology::Approval));
        EXPECT_EQ(interrupted.status(), ProgramTerminalStatus::Interrupted) << failure_text(interrupted);
        EXPECT_EQ(shared->transport.load(), 1);
        original = rows(files.provider_db());
    }
    // Resume attempt 2 in a copy of that state with one thing changed.
    ProgramResult resume_in_copy(const std::function<void(const TempDir&, Shared&, Options&)>& change,
                                 std::vector<Row>& after, int& transport) {
        TempDir copy("conflict-copy");
        copy_closed_files(files.path, copy.path);
        auto shared = std::make_shared<Shared>();
        shared->interrupt_after_call = true;
        Options options;
        options.model_tokens = 0;
        change(copy, *shared, options);
        Wire wire(copy, shared, options);
        auto result = wire.runtime().resume(owner, run, resume_after(interrupted, "trace-conflict")).wait();
        transport = shared->transport.load();
        after = rows(copy.provider_db());
        return result;
    }
    TempDir files;
    const std::string owner = "tenant:conflict";
    const std::string run = "conflict-run";
    ProgramResult interrupted;
    std::vector<Row> original;
};
} // namespace

TEST(ProgramProviderJournalRuntime, UnchangedBindingResumesAndEveryChangedBindingFailsClosed) {
    PausedWithCompletedCall paused;
    ASSERT_EQ(paused.original.size(), 1U);
    ASSERT_EQ(paused.original[0].state, "succeeded");

    std::vector<Row> after;
    int transport = -1;
    const auto control = paused.resume_in_copy([](const TempDir&, Shared&, Options&) {}, after, transport);
    EXPECT_EQ(control.status(), ProgramTerminalStatus::Completed) << failure_text(control);
    EXPECT_EQ(control.attempt(), 2U);
    EXPECT_EQ(transport, 0);
    EXPECT_TRUE(same_rows(after, paused.original));

    struct Change {
        const char* name;
        std::function<void(const TempDir&, Shared&, Options&)> apply;
    };
    const std::vector<Change> changes{
        {"deployment", [](const TempDir&, Shared&, Options& options) { options.deployment = digest('b'); }},
        {"model", [](const TempDir&, Shared& shared, Options&) { shared.node_model = "another-model"; }},
        {"request", [](const TempDir&, Shared& shared, Options&) { shared.node_prompt = "a different question"; }},
    };
    for (const auto& change : changes) {
        SCOPED_TRACE(change.name);
        const auto failed = paused.resume_in_copy(change.apply, after, transport);
        EXPECT_EQ(failed.status(), ProgramTerminalStatus::Failed);
        EXPECT_EQ(failed.attempt(), 2U);
        EXPECT_EQ(transport, 0) << "a conflicting call must not reach the Provider";
        EXPECT_TRUE(same_rows(after, paused.original)) << "and must not rewrite the journal";
    }
    // The persisted record itself disagrees with what the runtime derives for this slot.
    const std::vector<std::pair<const char*, std::string>> tampering{
        {"slot", "UPDATE ng_program_provider_calls SET slot=replace(slot,'\"call_ordinal\":0','\"call_ordinal\":1')"},
        {"request_digest", "UPDATE ng_program_provider_calls SET request_digest='sha256:" + std::string(64, 'e') + "'"},
        {"provider_binding_identity", "UPDATE ng_program_provider_calls SET provider_binding_identity='sha256:" + std::string(64, 'e') + "'"},
        {"model", "UPDATE ng_program_provider_calls SET model='forged-model'"},
        {"provider_name", "UPDATE ng_program_provider_calls SET provider_name='forged-provider'"},
        {"family", "UPDATE ng_program_provider_calls SET family='anthropic.messages'"},
        {"mode", "UPDATE ng_program_provider_calls SET mode='stream'"},
    };
    for (const auto& [column, sql] : tampering) {
        SCOPED_TRACE(column);
        std::vector<Row> tampered;
        const auto failed = paused.resume_in_copy(
            [&](const TempDir& copy, Shared&, Options&) {
                Connection(copy.provider_db()).exec(sql);
                tampered = rows(copy.provider_db());
            }, after, transport);
        EXPECT_EQ(failed.status(), ProgramTerminalStatus::Failed);
        EXPECT_EQ(failed.attempt(), 2U);
        EXPECT_EQ(transport, 0);
        EXPECT_FALSE(same_rows(tampered, paused.original)) << "the tampering changed the row";
        EXPECT_TRUE(same_rows(after, tampered)) << "the runtime neither repaired nor rewrote it";
    }
}

