TEST(ProgramProviderJournalRuntime, ReActSecondTurnAfterToolObservationGetsNewSlot) {
    TempDir files("react");
    auto shared = std::make_shared<Shared>();
    shared->script = Script::React;
    const std::string owner = "tenant:react";
    std::string version_id;
    {
        Wire wire(files, shared);
        const auto version = wire.admit(owner, Topology::React);
        version_id = version.id();
        const auto result = wire.runtime().run(owner, version,
                                               wire.invocation("react-run", "question", Topology::React));
        ASSERT_EQ(result.status(), ProgramTerminalStatus::Completed) << failure_text(result);
        EXPECT_NE(result.output().dump().find("answer(question|tool-observation)"), std::string::npos);
    }
    EXPECT_EQ(shared->transport.load(), 2);
    EXPECT_EQ(shared->tool_executions.load(), 1);
    const auto observed = shared->snapshot();
    ASSERT_EQ(observed.size(), 2U);
    EXPECT_FALSE(observed[0].observation);
    EXPECT_TRUE(observed[1].observation) << "the second turn carried the Tool observation";

    const auto all = rows(files.provider_db());
    ASSERT_EQ(all.size(), 2U);
    const auto& first = all[0];
    const auto& second = all[1];
    EXPECT_NE(first.id, second.id);
    EXPECT_NE(first.request, second.request);
    for (const auto* row : {&first, &second}) {
        EXPECT_EQ(row->state, "succeeded");
        EXPECT_EQ(row->original_attempt, "1");
        EXPECT_EQ(row->slot.at("owner_scope"), owner);
        EXPECT_EQ(row->slot.at("program_version_id"), version_id);
        EXPECT_EQ(row->slot.at("run_id"), "react-run");
        EXPECT_EQ(row->slot.at("operation_id"), "root");
        EXPECT_EQ(row->slot.at("node_name"), "llm");
        EXPECT_EQ(row->slot.at("call_ordinal"), 0);
    }
    EXPECT_EQ(first.slot.at("thread_id"), second.slot.at("thread_id"));
    EXPECT_NE(first.slot.at("task_id"), second.slot.at("task_id"))
        << "the second turn is a new task of the same node";

    Wire reopened(files, shared);
    const auto restored = reopened.runtime().reconnect(owner, "react-run").wait();
    EXPECT_EQ(restored.status(), ProgramTerminalStatus::Completed);
    EXPECT_EQ(shared->transport.load(), 2);
    EXPECT_EQ(shared->tool_executions.load(), 1);
    EXPECT_TRUE(same_rows(rows(files.provider_db()), all));
}

TEST(ProgramProviderJournalRuntime, ReActResumedAtAdvancedAttemptKeepsFirstSlotAndAddsSecond) {
    TempDir files("react-resume");
    auto shared = std::make_shared<Shared>();
    shared->script = Script::React;
    const std::string owner = "tenant:react";
    ProgramResult paused;
    std::vector<Row> first_turn;
    {
        Wire wire(files, shared);
        const auto version = wire.admit(owner, Topology::ReactPausedBeforeTools);
        paused = wire.runtime().run(owner, version,
                                    wire.invocation("react-run", "question", Topology::ReactPausedBeforeTools));
        ASSERT_EQ(paused.status(), ProgramTerminalStatus::Interrupted) << failure_text(paused);
        EXPECT_EQ(shared->transport.load(), 1);
        EXPECT_EQ(shared->tool_executions.load(), 0);
        first_turn = rows(files.provider_db());
        ASSERT_EQ(first_turn.size(), 1U);
    }
    Wire reopened(files, shared);
    const auto resumed = reopened.runtime().resume(owner, "react-run",
        resume_after(paused, "trace-react-resume", json(nullptr))).wait();
    ASSERT_EQ(resumed.status(), ProgramTerminalStatus::Completed) << failure_text(resumed);
    EXPECT_EQ(resumed.attempt(), 2U);
    EXPECT_EQ(shared->transport.load(), 2);
    EXPECT_EQ(shared->tool_executions.load(), 1);
    EXPECT_NE(resumed.output().dump().find("answer(question|tool-observation)"), std::string::npos);
    const auto all = rows(files.provider_db());
    ASSERT_EQ(all.size(), 2U);
    EXPECT_TRUE(same_rows({all[0]}, first_turn)) << "turn one is untouched by the advanced attempt";
    EXPECT_EQ(all[0].original_attempt, "1");
    EXPECT_EQ(all[1].original_attempt, "2") << "turn two is a new slot first dispatched in attempt 2";
    EXPECT_NE(all[0].id, all[1].id);
    EXPECT_EQ(all[0].slot.at("thread_id"), all[1].slot.at("thread_id"));
}
